import{c as t,Q as a,j as r,m as o}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Autonomous Event-Driven Multi-Agent Orchestration for Enterprise AI at Scale","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.20058","title":"Autonomous Event-Driven Multi-Agent Orchestration for Enterprise AI at Scale","archived_date":"2026-07-31T00:00:00.000Z","arxiv_id":2606.20058,"authors":["Harsh Rao Dhanyamraju","Leonidas Raghav","Aaron Lee"],"collected_at":"2026-07-31T00:00:00.000Z","collected_by":"routine-d","domain":"multi-agent","pdf_path":"pdfs/2606.20058.pdf","published_date":"2026-06-18T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-06-18-autonomous-event-driven-multi-agent-orchestration-enterprise-2606-20058.md","filePath":"research/papers/2026-06-18-autonomous-event-driven-multi-agent-orchestration-enterprise-2606-20058.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-06-18-autonomous-event-driven-multi-agent-orchestration-enterprise-2606-20058.md"};function s(i,e,c,d,u,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="autonomous-event-driven-multi-agent-orchestration-for-enterprise-ai-at-scale" tabindex="-1">Autonomous Event-Driven Multi-Agent Orchestration for Enterprise AI at Scale <a class="header-anchor" href="#autonomous-event-driven-multi-agent-orchestration-for-enterprise-ai-at-scale" aria-label="Permalink to &quot;Autonomous Event-Driven Multi-Agent Orchestration for Enterprise AI at Scale&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>針對企業級多代理部署（小團隊到 200 代理規模）系統性比較編排策略，發現「規模而非任務複雜度」才是決定編排效能的主因，且代理探索（agent discovery）在大規模部署時成為主要瓶頸。作者引入 Task Manager 元件，在 208 個源自生產環境的企業場景評測中，將高優先序佇列延遲降低 14–75%，相關事件正確率提升逾 20 個百分點。</p><h2 id="與-harness-的關聯" tabindex="-1">與 Harness 的關聯 <a class="header-anchor" href="#與-harness-的關聯" aria-label="Permalink to &quot;與 Harness 的關聯&quot;">​</a></h2><p>「規模主導編排效能、探索成本才是瓶頸」的結論，直接對應 <code>core.md §PROPOSE 委派</code>（原 <code>graph.md §G3</code>）「fan-out 有上限」與委派拓撲設計——當節點數增加，發現/路由成本會蓋過任務本身複雜度，是設計 Handoff Contract 與速率閘時的量化佐證。 〔v5.1：所引 workspace 細則已退役 → 見 <code>INDEX.md</code> §v5.1 規則退役對照〕</p>',5)])])}const m=t(n,[["render",s]]);export{p as __pageData,m as default};
